effect.shader:
float hash11(float x) { return fract(sin(x * 127.1) * 43758.5453); }

void main() {
    float t = acTime + seed * 11.0;
    float a1 = hash11(floor(t * rate1)) * 2.0 - 1.0;
    float b1 = hash11(floor(t * rate1) + 7.3) * 2.0 - 1.0;
    float a2 = hash11(floor(t * rate2) + 3.1) * 2.0 - 1.0;
    float b2 = hash11(floor(t * rate2) + 9.7) * 2.0 - 1.0;

    vec2 shift = vec2(a1 + 0.4 * a2, b1 + 0.4 * b2) * amount;
    float ang = radians((a1 - b2) * rot);

    vec2 p = acScreenNorm - vec2(0.5);
    p.x *= acAspect;
    float c = cos(ang), s = sin(ang);
    p = vec2(p.x * c - p.y * s, p.x * s + p.y * c);
    p.x /= acAspect;
    fragColor = texture(inputImg, p + vec2(0.5) + shift);
}
